const test=require('node:test');
const assert=require('node:assert/strict');
const {parseClock}=require('../clock.cjs');
test('valid clocks',()=>{
  assert.equal(parseClock('0:00'),0);
  assert.equal(parseClock('12:09'),729);
  assert.equal(parseClock('001:05'),65);
  assert.equal(parseClock('150119987579016:31'),Number.MAX_SAFE_INTEGER);
});
test('strict syntax and range',()=>{
  for(const text of ['1:60','1:5','-1:05','1:05x',' 1:05','1:05\n','1:05:00','1.5:05','1e2:05','150119987579016:32','9007199254740993:00','']) {
    assert.throws(()=>parseClock(text),RangeError,text);
  }
});

