exports.parseClock = function(text) {
  const match=/^([0-9]+):([0-9]{2})$/.exec(text);
  if(!match || match[0] !== text || Number(match[2])>59) throw new RangeError('invalid clock');
  const total=BigInt(match[1])*60n+BigInt(match[2]);
  if(total>BigInt(Number.MAX_SAFE_INTEGER)) throw new RangeError('unsafe total');
  return Number(total);
};

